<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRouter,onBeforeRouteLeave} from 'vue-router'
import {useAuth} from '../../entities/auth/model'
import {request,errorMessage,isCancelled} from '../../shared/api/client'
import type {CallDetail,Taxonomy} from '../../shared/interfaces'
import {kindLabels,datetime} from '../../shared/lib/format'
import Icon from '../../shared/ui/Icon.vue'
import Notice from '../../shared/ui/Notice.vue'
import Empty from '../../shared/ui/Empty.vue'
import AnalysisBadge from '../processing/AnalysisBadge.vue'
const props=defineProps<{callId:string}>(),emit=defineEmits<{(e:'close'):void;(e:'saved'):void}>(),auth=useAuth(),router=useRouter()
const detail=ref<CallDetail|null>(null),taxonomy=ref<Taxonomy>({tags:[],statuses:[]}),loading=ref(true),error=ref(''),success=ref(''),saving=ref(false),dirty=ref(false),confirmClose=ref(false),panel=ref<HTMLElement>(),note=ref(''),status=ref<string|null>(null),tags=ref<string[]>([]),kind=ref('unknown'),locked=ref(true),version=ref(0)
const editingId=ref(props.callId),pendingRoute=ref('')
const call=computed(()=>detail.value?.call)
let previousFocus:HTMLElement|null=null,timer:ReturnType<typeof setInterval>|undefined,loadGeneration=0
function adopt(){if(!call.value||dirty.value)return;note.value=call.value.note||'';status.value=call.value.status_id;tags.value=[...call.value.tag_ids];kind.value=call.value.contact_kind;locked.value=call.value.manual_lock;version.value=call.value.version}
async function load(background=false){const generation=++loadGeneration,id=editingId.value;if(!background)loading.value=true;try{const[d,t]=await Promise.all([request<CallDetail>('/calls/'+encodeURIComponent(id)),request<Taxonomy>('/taxonomy')]);if(generation!==loadGeneration||id!==editingId.value)return;detail.value=d;taxonomy.value=t;adopt();if(!dirty.value)error.value=''}catch(e){if(!isCancelled(e)&&generation===loadGeneration)error.value=errorMessage(e)}finally{if(generation===loadGeneration)loading.value=false}}
function toggle(id:string){tags.value=tags.value.includes(id)?tags.value.filter(t=>t!==id):[...tags.value,id];dirty.value=true}
async function save(){if(!call.value||saving.value||!auth.canWrite)return;saving.value=true;error.value='';success.value='';try{await request('/calls/'+encodeURIComponent(call.value.id),{method:'PATCH',body:{status_id:status.value||null,tag_ids:tags.value,note:note.value,contact_kind:kind.value,manual_lock:locked.value,version:version.value}});dirty.value=false;success.value='Изменения сохранены';emit('saved');await load(true)}catch(e){if(!isCancelled(e))error.value=errorMessage(e)}finally{saving.value=false}}
function close(){if(saving.value)return;if(dirty.value){confirmClose.value=true;return}emit('close')}
function discard(){dirty.value=false;confirmClose.value=false;const destination=pendingRoute.value;pendingRoute.value='';emit('close');if(destination)router.push(destination)}
function openCall(){if(!call.value||saving.value)return;if(dirty.value){pendingRoute.value='/calls/'+call.value.id;confirmClose.value=true;return}emit('close');router.push('/calls/'+call.value.id)}
onBeforeRouteLeave(to=>{if(dirty.value){pendingRoute.value=to.fullPath;confirmClose.value=true;return false}if(saving.value)return false;return true})
function keydown(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();confirmClose.value?confirmClose.value=false:close()}else if(event.key==='Tab'&&panel.value){const nodes=[...panel.value.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(n=>n.getAttribute('aria-hidden')!=='true'&&!n.closest('[hidden],[aria-hidden="true"]'));const first=nodes[0],last=nodes.at(-1);if(!first||!last){event.preventDefault();panel.value.focus()}else if(event.shiftKey&&(document.activeElement===first||document.activeElement===panel.value)){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}}
onMounted(async()=>{previousFocus=document.activeElement as HTMLElement;document.addEventListener('keydown',keydown);await load();await nextTick();panel.value?.focus();timer=setInterval(()=>{if(!document.hidden&&!saving.value)load(true)},15000)})
onUnmounted(()=>{loadGeneration++;clearInterval(timer);document.removeEventListener('keydown',keydown);previousFocus?.focus()})
watch(()=>props.callId,(next)=>{if(dirty.value){error.value='Сначала сохрани или закрой текущую разметку';confirmClose.value=true;return}editingId.value=next;dirty.value=false;confirmClose.value=false;success.value='';detail.value=null;load()})
</script>
<template><div class="call-actions-shade" @click.self="close"><aside ref="panel" class="call-actions-panel" role="dialog" aria-modal="true" aria-labelledby="call-actions-heading" tabindex="-1"><header class="call-actions-header"><div><span class="eyebrow">Работа со звонком</span><h2 id="call-actions-heading">Разметка и заметки</h2></div><button class="icon-button" aria-label="Закрыть панель звонка" :disabled="saving" @click="close"><Icon name="close"/></button></header><div class="call-actions-body"><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/><Empty v-if="loading&&!detail" loading/><template v-else-if="call"><div class="call-actions-contact"><b>{{call.contact_name||call.phone||'Скрытый номер'}}</b><p>{{datetime(call.started_at,auth.me?.organization.timezone)}} · {{call.employee||'Не назначен'}}</p><AnalysisBadge :call="call"/><RouterLink class="text-link" :to="'/calls/'+call.id" @click.prevent="openCall">Открыть запись и расшифровку →</RouterLink></div><Notice v-if="!auth.canWrite" message="У тебя доступ только для просмотра."/><form class="call-actions-form" @submit.prevent="save"><label>Бизнес-статус<select v-model="status" :disabled="!auth.canWrite||saving" @change="dirty=true"><option :value="null">Не назначен</option><option v-for="s in taxonomy.statuses.filter(s=>!s.archived||s.id===status)" :key="s.id" :value="s.id">{{s.name}}{{s.archived?' (архив)':''}}</option></select></label><label>Тип обращения<select v-model="kind" :disabled="!auth.canWrite||saving" @change="dirty=true"><option v-for="(label,value) in kindLabels" :key="value" :value="value">{{label}}</option></select></label><fieldset :disabled="!auth.canWrite||saving"><legend>Теги</legend><div class="inline-labels"><button v-for="tag in taxonomy.tags.filter(t=>!t.archived||tags.includes(t.id))" :key="tag.id" type="button" class="tag-toggle" :class="{selected:tags.includes(tag.id)}" :aria-pressed="tags.includes(tag.id)" @click="toggle(tag.id)">{{tag.name}}{{tag.archived?' (архив)':''}}</button><span v-if="!taxonomy.tags.length" class="subtle">Добавь теги в настройках компании</span></div></fieldset><label>Комментарий<textarea v-model="note" :disabled="!auth.canWrite||saving" placeholder="Что важно учесть при следующем контакте" @input="dirty=true"></textarea></label><label class="checkbox"><input v-model="locked" type="checkbox" :disabled="!auth.canWrite||saving" @change="dirty=true"/>Защитить разметку от автоматической замены</label><button v-if="auth.canWrite" class="button primary full" type="submit" :disabled="saving||!dirty">{{saving?'Сохраняем…':'Сохранить изменения'}}</button></form></template><Empty v-else title="Звонок недоступен" description="Проверь соединение или открой другой звонок."/></div><div v-if="confirmClose" class="call-actions-confirm" role="alertdialog" aria-label="Несохранённые изменения"><b>Есть несохранённые изменения</b><p>Сохранить их можно кнопкой в панели.</p><div class="row-actions"><button class="button" @click="confirmClose=false">Продолжить редактирование</button><button class="button danger" @click="discard">Закрыть без сохранения</button></div></div></aside></div></template>
